  places: ['germany', 'france', 'ireland', 'netherlands', 'spain', 'italy', 'switzerland', 'india', 'brazil', 'canada', 'australia', 'japan', 'singapore', 'china', 'apac', 'emea', 'latam', 'south america', 'north america', 'middle east', 'africa', 'asia'],
